CREATE TABLE animals (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  sci_name     TEXT,
  emoji        TEXT,
  tier         TEXT CHECK (tier IN ('L','S','A','B','C','D')),
  tier_label   TEXT,
  pts          INT,
  status       TEXT,
  status_label TEXT,
  where_find   TEXT,
  habitat      TEXT,
  wiki_url     TEXT,
  is_active    BOOLEAN DEFAULT TRUE
);

ALTER TABLE animals ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Animals are publicly viewable"
  ON animals FOR SELECT
  USING (TRUE);

